## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/afAblationLogic.ts`

```typescript
// Atrial Fibrillation Catheter Ablation Clinical Decision Logic
// Based on: 2023 ACC/AHA/ACCP/HRS Guideline for Diagnosis and Management of Atrial Fibrillation
// Reference: Joglar JA, et al. J Am Coll Cardiol. 2024;83(1):109-279. PMID: 38033089
// Also: 2017 HRS/EHRA/ECAS/APHRS/SOLAECE Expert Consensus Statement on Catheter Ablation of AF

export interface AFAblationInput {
  // Patient demographics
  age: number;
  sex: 'male' | 'female';

  // AF type and burden
  afType: 'paroxysmal' | 'persistent' | 'longstanding-persistent' | 'permanent';
  afDuration: number; // months since first diagnosis
  symptomBurden: 'none' | 'mild' | 'moderate' | 'severe'; // EHRA/AFEQT class

  // CHA2DS2-VASc components
  chf: boolean;
  hypertension: boolean;
  age75orOlder: boolean;
  diabetes: boolean;
  stroke: boolean; // prior stroke/TIA/thromboembolism
  vascularDisease: boolean; // prior MI, PAD, aortic plaque
  age65to74: boolean;
  femaleSex: boolean; // already captured in sex field

  // Antiarrhythmic drug history
  aadFailed: boolean; // failed ≥1 Class I or III AAD
  aadIntolerant: boolean; // intolerant to AADs
  aadTrialed: string[]; // list of AADs tried

  // Structural heart disease
  lvef: number; // percent
  laSize: number; // left atrial diameter in mm
  structuralHeartDisease: boolean;
  hcm: boolean; // hypertrophic cardiomyopathy

  // Comorbidities
  sleepApnea: boolean;
  sleepApneaTreated: boolean;
  obesity: boolean; // BMI ≥30
  bmi: number;
  thyroidDisease: boolean;
  thyroidTreated: boolean;
  ckdStage: 0 | 1 | 2 | 3 | 4 | 5;

  // Anticoagulation
  onAnticoagulation: boolean;
  anticoagulantType: 'DOAC' | 'warfarin' | 'none';

  // Contraindications
  activeInfection: boolean;
  recentThrombus: boolean; // LAA thrombus on TEE
  uncontrolledHF: boolean;
  severeMitralStenosis: boolean;
}

export interface AFAblationResult {
  candidacyScore: number; // 0–100
  cha2ds2vascScore: number;
  recommendation: 'Strongly Recommended' | 'Recommended' | 'Reasonable' | 'Not Recommended';
  guidelineClass: string;
  preferredApproach: string;
  keyFindings: string[];
  warnings: string[];
  anticoagulationNote: string;
  references: string[];
}

function calcCHA2DS2VASc(input: AFAblationInput): number {
  let score = 0;
  if (input.chf) score += 1;
  if (input.hypertension) score += 1;
  if (input.age75orOlder) score += 2;
  if (input.diabetes) score += 1;
  if (input.stroke) score += 2;
  if (input.vascularDisease) score += 1;
  if (input.age65to74) score += 1;
  if (input.sex === 'female') score += 1;
  return score;
}

export function calculateAFAblationScore(input: AFAblationInput): AFAblationResult {
  const warnings: string[] = [];
  const keyFindings: string[] = [];
  let score = 0;

  const cha2ds2vascScore = calcCHA2DS2VASc(input);

  // Absolute contraindications
  if (input.recentThrombus) {
    warnings.push('CONTRAINDICATION: LAA thrombus on TEE — ablation contraindicated until thrombus resolves with anticoagulation');
    return {
      candidacyScore: 0,
      cha2ds2vascScore,
      recommendation: 'Not Recommended',
      guidelineClass: 'Class III: Harm',
      preferredApproach: 'Anticoagulate for ≥3 weeks and repeat TEE before reconsidering ablation',
      keyFindings,
      warnings,
      anticoagulationNote: 'Anticoagulation required; repeat TEE in 3–6 weeks',
      references: [],
    };
  }

  if (input.activeInfection) {
    warnings.push('CONTRAINDICATION: Active infection — defer ablation until resolved');
  }

  // AF type and symptom burden — primary drivers
  if (input.afType === 'paroxysmal') {
    score += 25;
    keyFindings.push('Paroxysmal AF — highest success rates with pulmonary vein isolation (PVI)');
  } else if (input.afType === 'persistent') {
    score += 20;
    keyFindings.push('Persistent AF — PVI with possible additional substrate modification; success rates 60–80%');
  } else if (input.afType === 'longstanding-persistent') {
    score += 10;
    keyFindings.push('Long-standing persistent AF — lower success rates; may require staged procedures');
    warnings.push('Long-standing persistent AF — discuss realistic success rates (50–60%) and possible need for repeat procedures');
  } else {
    warnings.push('Permanent AF — ablation generally not indicated unless rhythm control strategy is being re-initiated');
    score -= 20;
  }

  if (input.symptomBurden === 'severe') {
    score += 25;
    keyFindings.push('Severe symptom burden — ablation strongly supported for quality-of-life improvement');
  } else if (input.symptomBurden === 'moderate') {
    score += 15;
    keyFindings.push('Moderate symptoms — ablation appropriate after AAD failure or as first-line option');
  } else if (input.symptomBurden === 'mild') {
    score += 5;
  } else {
    warnings.push('Asymptomatic AF — ablation benefit primarily for rhythm control; discuss risks vs benefits');
    score -= 10;
  }

  // AAD history
  if (input.aadFailed) {
    score += 20;
    keyFindings.push(`Failed AAD therapy (${input.aadTrialed.join(', ')}) — ablation is Class I indication`);
  } else if (input.aadIntolerant) {
    score += 15;
    keyFindings.push('AAD intolerance — ablation reasonable as alternative rhythm control strategy');
  } else {
    keyFindings.push('No prior AAD trial — ablation may be considered as first-line per 2023 ACC/AHA guidelines (Class IIa for paroxysmal AF)');
    score += 5;
  }

  // LA size
  if (input.laSize > 55) {
    warnings.push(`Markedly enlarged LA (${input.laSize} mm) — significantly reduced ablation success; consider rate control`);
    score -= 15;
  } else if (input.laSize > 45) {
    warnings.push(`Enlarged LA (${input.laSize} mm) — reduced success rates; discuss expectations`);
    score -= 5;
  } else {
    keyFindings.push(`LA size ${input.laSize} mm — favorable anatomy for ablation`);
    score += 5;
  }

  // LVEF
  if (input.lvef < 35) {
    keyFindings.push(`Reduced LVEF (${input.lvef}%) — tachycardia-mediated cardiomyopathy possible; ablation may improve EF (CASTLE-AF)`);
    score += 10;
  }

  // HCM
  if (input.hcm) {
    keyFindings.push('HCM with AF — ablation reasonable; higher recurrence rates; specialized center recommended');
  }

  // Modifiable risk factors
  if (input.sleepApnea && !input.sleepApneaTreated) {
    warnings.push('Untreated obstructive sleep apnea — treat OSA before ablation to reduce recurrence risk');
    score -= 5;
  }
  if (input.obesity && input.bmi >= 35) {
    warnings.push(`BMI ${input.bmi} — weight loss to BMI <30 significantly improves ablation outcomes (LEGACY trial)`);
    score -= 5;
  }
  if (input.thyroidDisease && !input.thyroidTreated) {
    warnings.push('Untreated thyroid disease — correct thyroid function before ablation');
    score -= 10;
  }

  // Anticoagulation
  if (!input.onAnticoagulation && cha2ds2vascScore >= 2) {
    warnings.push(`CHA₂DS₂-VASc score ${cha2ds2vascScore} — anticoagulation required; start before ablation`);
  }

  score = Math.max(0, Math.min(100, score));

  let recommendation: AFAblationResult['recommendation'];
  let guidelineClass: string;
  let preferredApproach: string;

  if (score >= 65) {
    recommendation = 'Strongly Recommended';
    guidelineClass = 'Class I: Catheter ablation is recommended';
    preferredApproach = 'Pulmonary vein isolation (PVI) — radiofrequency or cryoablation; continue anticoagulation peri-procedurally';
  } else if (score >= 45) {
    recommendation = 'Recommended';
    guidelineClass = 'Class IIa: Catheter ablation is reasonable';
    preferredApproach = 'PVI with electrophysiology consultation; optimize modifiable risk factors pre-procedure';
  } else if (score >= 25) {
    recommendation = 'Reasonable';
    guidelineClass = 'Class IIb: Catheter ablation may be considered';
    preferredApproach = 'Shared decision-making; address modifiable risk factors; consider rate control if ablation risks outweigh benefits';
  } else {
    recommendation = 'Not Recommended';
    guidelineClass = 'Class III: Ablation not recommended in current clinical context';
    preferredApproach = 'Rate control strategy; optimize anticoagulation; reassess in 6–12 months';
  }

  const anticoagulationNote = cha2ds2vascScore >= 2
    ? `CHA₂DS₂-VASc ${cha2ds2vascScore} — long-term anticoagulation recommended regardless of ablation outcome (Class I)`
    : cha2ds2vascScore === 1 && input.sex !== 'female'
    ? `CHA₂DS₂-VASc ${cha2ds2vascScore} — anticoagulation may be considered (Class IIb)`
    : `CHA₂DS₂-VASc ${cha2ds2vascScore} — anticoagulation not routinely recommended; reassess annually`;

  return {
    candidacyScore: score,
    cha2ds2vascScore,
    recommendation,
    guidelineClass,
    preferredApproach,
    keyFindings,
    warnings,
    anticoagulationNote,
    references: [
      'Joglar JA, et al. 2023 ACC/AHA/ACCP/HRS Guideline for Diagnosis and Management of Atrial Fibrillation. J Am Coll Cardiol. 2024;83(1):109-279. PMID: 38033089',
      'Calkins H, et al. 2017 HRS/EHRA/ECAS/APHRS/SOLAECE Expert Consensus Statement on Catheter Ablation of AF. Heart Rhythm. 2017;14(10):e275-e444. PMID: 28506916',
      'Marrouche NF, et al. CASTLE-AF Trial. Catheter Ablation for AF with Heart Failure. N Engl J Med. 2018;378(5):417-427. PMID: 29385358',
      'Packer DL, et al. CABANA Trial. Catheter Ablation vs Medical Therapy for AF. JAMA. 2019;321(13):1261-1274. PMID: 30874766',
      'Pathak RK, et al. LEGACY Trial. Long-Term Effect of Goal-Directed Weight Management on AF. J Am Coll Cardiol. 2015;65(20):2159-2169. PMID: 25997708',
    ],
  };
}
